 async function refresh(){const sequence=++refreshSequence.current;try{let r=await fetch('/api/platform'+(currentSelected.current?'?order='+currentSelected.current:''));if([403,404].includes(r.status)&&currentSelected.current)r=await fetch('/api/platform');if(sequence!==refreshSequence.current)return;if(r.status===401){setData(null);return;}const j:any=await r.json();if(sequence!==refreshSequence.current)return;if(!r.ok)throw new Error(j.error);setData(j);setRates(normalizeRates(j.rates));if(ready.current&&'Notification' in window&&Notification.permission==='granted'){for(const n of j.notifications||[])if(!n.read&&!seen.current.has(n.id)){const notification=new Notification('Black to White',{body:n.text,tag:n.id});notification.onclick=()=>{window.focus();if(n.order_id){setSelected(n.order_id);setView('detail');}};}}for(const n of j.notifications||[])seen.current.add(n.id);ready.current=true;}catch(e:any){setError(e.message);}finally{setAuthLoading(false);}}
